+			b, _ := NewTracerPair(tracer)
+			span := b.StartSpan("test").(*bridgeSpan)
+
+			tc.log(span)
+
+			mockSpan := span.otelSpan.(*mockSpan)
+			require.Len(t, mockSpan.Events, 1)
+			assert.Equal(t, tc.expected, mockSpan.Events[0].Name)
+		})
+	}
+}
